import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        int m = sc.nextInt();

        int[][] g = new int[n][m];
        long mismatch0 = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                g[i][j] = sc.nextInt();
                int desired = (i + j) & 1;
                if ((g[i][j] & 1) != desired) {
                    mismatch0++;
                }
            }
        }

        long total = (long) n * m;
        long mismatch1 = total - mismatch0;

        boolean usePattern0 = mismatch0 <= mismatch1;
        long answer = Math.min(mismatch0, mismatch1);

        StringBuilder sb = new StringBuilder();
        sb.append(answer).append('\n');

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int desired = (i + j) & 1;
                if (!usePattern0) {
                    desired ^= 1;
                }

                int val = g[i][j];
                if ((val & 1) != desired) {
                    val++;
                }

                sb.append(val);
                if (j + 1 < m) {
                    sb.append(' ');
                } else {
                    sb.append('\n');
                }
            }
        }

        System.out.print(sb.toString());
    }
}
```

